class Solution {
    public String sortSentence(String s) {
        String[] tokens = s.split(" ");
        String[] ordered = new String[tokens.length];
        for (String token : tokens) {
            int position = token.charAt(token.length() - 1) - '1';
            ordered[position] = token.substring(0, token.length() - 1);
        }
        return String.join(" ", ordered);
    }
}

import java.util.Arrays;

class Solution {
    public String sortSentence(String s) {
        String[] tokens = s.split(" ");
        Arrays.sort(tokens, (left, right) -> left.charAt(left.length() - 1) - right.charAt(right.length() - 1));

        StringBuilder answer = new StringBuilder();
        for (int i = 0; i < tokens.length; i++) {
            if (i > 0) {
                answer.append(' ');
            }
            answer.append(tokens[i], 0, tokens[i].length() - 1);
        }
        return answer.toString();
    }
}

class Solution {
    public String sortSentence(String s) {
        String[] slots = new String[9];
        int wordCount = 0;
        int start = 0;

        for (int i = 0; i <= s.length(); i++) {
            if (i == s.length() || s.charAt(i) == ' ') {
                int position = s.charAt(i - 1) - '1';
                slots[position] = s.substring(start, i - 1);
                wordCount++;
                start = i + 1;
            }
        }

        StringBuilder answer = new StringBuilder();
        for (int i = 0; i < wordCount; i++) {
            if (i > 0) {
                answer.append(' ');
            }
            answer.append(slots[i]);
        }
        return answer.toString();
    }
}

class Solution {
    public String sortSentence(String s) {
        StringBuilder[] slots = new StringBuilder[9];
        StringBuilder current = new StringBuilder();
        int wordCount = 0;

        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);
            if (ch == ' ') {
                current.setLength(0);
            } else if (ch >= '1' && ch <= '9') {
                slots[ch - '1'] = new StringBuilder(current);
                wordCount++;
                current.setLength(0);
            } else {
                current.append(ch);
            }
        }

        StringBuilder answer = new StringBuilder();
        for (int i = 0; i < wordCount; i++) {
            if (i > 0) {
                answer.append(' ');
            }
            answer.append(slots[i]);
        }
        return answer.toString();
    }
}
